cd /testbed && patch -p1 <<'PATCH'
--- a/tests/unit/cluster/cluster-shards.tcl
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,89 @@
+proc cluster_shards_slots_by_node {reference} {
+    set slots_by_node [dict create]
+    foreach shard [R $reference cluster shards] {
+        foreach node [dict get $shard nodes] {
+            dict set slots_by_node [dict get $node id] [dict get $shard slots]
+        }
+    }
+    return $slots_by_node
+}
+
+proc cluster_shards_allocate_slots {masters replicas} {
+    R 0 cluster addslotsrange 0 1000 1002 5461
+    R 1 cluster addslotsrange 5462 10922
+    R 2 cluster addslotsrange 1001 1001 10923 16383
+}
+
+start_cluster 3 3 {tags {external:skip cluster}} {
+    set expected_slots [dict create]
+    set ranges {{0 1000 1002 5461} {5462 10922} {1001 1001 10923 16383}}
+    for {set i 0} {$i < 6} {incr i} {
+        dict set expected_slots [R $i cluster myid] [lindex $ranges [expr {$i % 3}]]
+    }
+    set old_primary_id [R 0 cluster myid]
+    set new_primary_id [R 3 cluster myid]
+
+    test "CLUSTER SHARDS reports all slot ranges on primaries and replicas" {
+        for {set ref 0} {$ref < 6} {incr ref} {
+            set actual_slots [cluster_shards_slots_by_node $ref]
+            assert_equal 6 [dict size $actual_slots]
+            dict for {id slots} $expected_slots {
+                assert_equal $slots [dict get $actual_slots $id]
+            }
+        }
+    }
+
+    test "CLUSTER SHARDS preserves slot ranges after failover with the old primary stopped" {
+        set paused_pid [srv 0 pid]
+        pause_process $paused_pid
+        R 3 cluster failover takeover
+
+        for {set ref 1} {$ref < 6} {incr ref} {
+            wait_for_condition 1000 50 {
+                [lindex [R $ref cluster slots] 0 2 2] eq $new_primary_id
+            } else {
+                fail "Node $ref did not learn the new slot owner"
+            }
+
+            # The stopped primary cannot announce its demotion.
+            assert {[cluster_has_flag [cluster_get_node_by_id $ref $old_primary_id] master]}
+            for {set attempt 0} {$attempt < 2} {incr attempt} {
+                set actual_slots [cluster_shards_slots_by_node $ref]
+                assert_equal 6 [dict size $actual_slots]
+                dict for {id slots} $expected_slots {
+                    assert_equal $slots [dict get $actual_slots $id]
+                }
+            }
+        }
+        resume_process $paused_pid
+    }
+
+    test "CLUSTER SHARDS preserves slot ranges after the old primary rejoins" {
+        wait_for_condition 1000 50 {
+            [s 0 role] eq {slave}
+        } else {
+            fail "Old primary was not converted into a replica"
+        }
+        wait_for_cluster_propagation
+        for {set ref 0} {$ref < 6} {incr ref} {
+            set actual_slots [cluster_shards_slots_by_node $ref]
+            dict for {id slots} $expected_slots {
+                assert_equal $slots [dict get $actual_slots $id]
+            }
+        }
+    }
+
+    test "CLUSTER SHARDS returns empty slots for a shard that owns no slots" {
+        R 3 cluster delslotsrange {*}[lindex $ranges 0]
+        set actual_slots [cluster_shards_slots_by_node 3]
+        assert_equal {} [dict get $actual_slots $old_primary_id]
+        assert_equal {} [dict get $actual_slots $new_primary_id]
+        for {set i 1} {$i < 3} {incr i} {
+            assert_equal [lindex $ranges $i] [dict get $actual_slots [R $i cluster myid]]
+        }
+    }
+} cluster_shards_allocate_slots
PATCH
./runtest --single unit/cluster/cluster-shards

